PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE inventory_items (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  price REAL NOT NULL,
  cost_price REAL DEFAULT 0,
  quantity INTEGER NOT NULL DEFAULT 0,
  unit TEXT,
  parent_id TEXT,
  pieces_per_parent INTEGER
, image_url TEXT, barcode TEXT, low_stock_level INTEGER, expiry_date TEXT, is_favorite INTEGER NOT NULL DEFAULT 0, category TEXT);
CREATE TABLE transactions (
  id TEXT PRIMARY KEY,
  item_id TEXT NOT NULL,
  item_name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('IN','OUT','UTANG','PAYMENT')),
  quantity INTEGER NOT NULL,
  total_price REAL NOT NULL,
  timestamp TEXT NOT NULL
, is_initial INTEGER DEFAULT 0, cost REAL);
CREATE TABLE utangs (
  id TEXT PRIMARY KEY,
  customer_name TEXT NOT NULL,
  items_description TEXT,
  amount REAL NOT NULL,
  date TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('UNPAID','PAID'))
, cost_total REAL DEFAULT 0, paid_amount REAL NOT NULL DEFAULT 0, cost REAL);
CREATE TABLE customers (
  name TEXT PRIMARY KEY
);
CREATE TABLE store_settings (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  store_name TEXT NOT NULL DEFAULT 'Sari-Sari Store',
  owner_name TEXT DEFAULT '',
  security_pin TEXT DEFAULT ''
, logo_url TEXT DEFAULT '');
CREATE TABLE expenses (
  id TEXT PRIMARY KEY,
  description TEXT NOT NULL,
  category TEXT,
  amount REAL NOT NULL,
  date TEXT NOT NULL
);
CREATE TABLE categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE COLLATE NOCASE,
  builtin_key TEXT,            -- which standard shelf this started as (so Auto-sort still works after a rename)
  position INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_transactions_timestamp ON transactions(timestamp);
CREATE INDEX idx_utangs_status ON utangs(status);
CREATE INDEX idx_items_parent ON inventory_items(parent_id);
CREATE INDEX idx_expenses_date ON expenses(date);
CREATE UNIQUE INDEX idx_items_barcode ON inventory_items(barcode) WHERE barcode IS NOT NULL;
